1	package server
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"fmt"
7		"sort"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// ChunkSize is the fixed split size for object bodies. All chunks except the
14	// final one have exactly this many bytes.
15	const ChunkSize = 1048576
16	
17	// MaxObjectSize is the largest accepted object body in bytes.
18	const MaxObjectSize = 67108864
19	
20	// cidPrefix prefixes every content identifier.
21	const cidPrefix = "sha256:"
22	
23	// object is a fully received object held in process memory.
24	type object struct {
25		cid    string
26		size   int
27		chunks [][]byte // raw chunk bytes, in reconstruction order
28		cids   []string // chunk identifiers, parallel to chunks
29	}
30	
31	// pin records a retention guarantee for one object. A nil expiresAt means
32	// the object is retained permanently; otherwise the pin is in force until
33	// the given instant. Pins live in process memory only and are not preserved
34	// across restarts.
35	type pin struct {
36		expiresAt *time.Time
37	}
38	
39	// validPin reports whether p is in force at now. Expired pins are
40	// equivalent to no pin at all.
41	func validPin(p pin, now time.Time) bool {
42		return p.expiresAt == nil || p.expiresAt.After(now)
43	}
44	
45	// blockRef holds one unique stored block. refs counts the live objects that
46	// reference the block; a block repeated within one object still counts once.
47	type blockRef struct {
48		data []byte
49		refs int
50	}
51	
52	// store is an in-process content-addressed object store. Objects are
53	// immutable once inserted; inserts and deletes happen under the write lock
54	// so readers never observe a partially written object. Blocks are stored
55	// once and shared by every object that references them; a block is dropped
56	// as soon as no live object references it.
57	type store struct {
58		mu      sync.RWMutex
59		objects map[string]*object
60		blocks  map[string]*blockRef
61		pins    map[string]pin
62		audit   *auditLog // nil until wired by the HTTP surface
63	}
64	
65	func newStore() *store {
66		return &store{
67			objects: make(map[string]*object),
68			blocks:  make(map[string]*blockRef),
69			pins:    make(map[string]pin),
70		}
71	}
72	
73	// chunkCID returns the identifier for one chunk's raw bytes.
74	func chunkCID(data []byte) string {
75		sum := sha256.Sum256(data)
76		return cidPrefix + hex.EncodeToString(sum[:])
77	}
78	
79	// rootCID derives the object identifier from the deterministic manifest: the
80	// total object length followed by the ordered chunk identifiers, encoded as
81	// "size:<N>\n" then one "<cid>\n" line per chunk.
82	func rootCID(size int, cids []string) string {
83		var b strings.Builder
84		fmt.Fprintf(&b, "size:%d\n", size)
85		for _, c := range cids {
86			b.WriteString(c)
87			b.WriteByte('\n')
88		}
89		sum := sha256.Sum256([]byte(b.String()))
90		return cidPrefix + hex.EncodeToString(sum[:])
91	}
92	
93	// put stores the object, or returns the existing one when the same root
94	// identifier is already present. Exactly one concurrent caller observes
95	// created == true for a given object. Newly stored objects register their
96	// unique chunks in the shared block table; repeated chunks within the
97	// object and chunks shared with other objects are stored only once. The
98	// audit event for the action is appended under the same lock, so event
99	// order matches commit order; providerID is set only for remote fetches.
100	func (s *store) put(obj *object, action string, providerID *string) (stored *object, created bool) {
101		s.mu.Lock()
102		defer s.mu.Unlock()
103		if existing, ok := s.objects[obj.cid]; ok {
104			s.audit.append(objectAuditRecord(action, existing, false, providerID))
105			return existing, false
106		}
107		s.objects[obj.cid] = obj
108		seen := make(map[string]bool, len(obj.cids))
109		for i, c := range obj.cids {
110			if b, ok := s.blocks[c]; ok {
111				obj.chunks[i] = b.data // share the stored copy
112				if !seen[c] {
113					b.refs++
114				}
115			} else {
116				s.blocks[c] = &blockRef{data: obj.chunks[i], refs: 1}
117			}
118			seen[c] = true
119		}
120		s.audit.append(objectAuditRecord(action, obj, true, providerID))
121		return obj, true
122	}
123	
124	// get returns the object for a root identifier, or nil when absent.
125	func (s *store) get(cid string) *object {
126		s.mu.RLock()
127		defer s.mu.RUnlock()
128		return s.objects[cid]
129	}
130	
131	// getBlock returns the raw bytes of a stored block, or nil when no live
132	// object references it.
133	func (s *store) getBlock(cid string) []byte {
134		s.mu.RLock()
135		defer s.mu.RUnlock()
136		if b, ok := s.blocks[cid]; ok {
137			return b.data
138		}
139		return nil
140	}
141	
142	// storageStats is a consistent snapshot of the store's occupancy.
143	type storageStats struct {
144		objects      int
145		logicalBytes int
146		blocks       int
147		storedBytes  int
148	}
149	
150	// stats snapshots object and deduplicated block occupancy under one lock
151	// hold, so the four counters always describe the same instant.
152	func (s *store) stats() storageStats {
153		s.mu.RLock()
154		defer s.mu.RUnlock()
155		st := storageStats{objects: len(s.objects), blocks: len(s.blocks)}
156		for _, obj := range s.objects {
157			st.logicalBytes += obj.size
158		}
159		for _, b := range s.blocks {
160			st.storedBytes += len(b.data)
161		}
162		return st
163	}
164	
165	// setPin pins cid with the given expiration, replacing any previous pin. It
166	// reports ok == false when the object does not exist. created is true when
167	// no valid pin was in force at now. The check and the update are atomic
168	// with respect to garbage collection.
169	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
170		s.mu.Lock()
171		defer s.mu.Unlock()
172		if _, exists := s.objects[cid]; !exists {
173			return false, false
174		}
175		existing, found := s.pins[cid]
176		created = !found || !validPin(existing, now)
177		s.pins[cid] = pin{expiresAt: expiresAt}
178		result := "updated"
179		if created {
180			result = "created"
181		}
182		s.audit.append(auditRecord{action: auditPinPut, result: result, cid: strPtr(cid)})
183		return created, true
184	}
185	
186	// removePin deletes the pin for cid, reporting whether a valid pin was in
187	// force at now. Expired pins are removed lazily and reported as absent.
188	func (s *store) removePin(cid string, now time.Time) bool {
189		s.mu.Lock()
190		defer s.mu.Unlock()
191		p, found := s.pins[cid]
192		if !found || !validPin(p, now) {
193			delete(s.pins, cid)
194			return false
195		}
196		delete(s.pins, cid)
197		s.audit.append(auditRecord{action: auditPinDelete, result: "deleted", cid: strPtr(cid)})
198		return true
199	}
200	
201	// pinEntry is one live pin in a listing.
202	type pinEntry struct {
203		cid       string
204		expiresAt *time.Time
205	}
206	
207	// listPins returns the pins in force at now, sorted by cid.
208	func (s *store) listPins(now time.Time) []pinEntry {
209		s.mu.RLock()
210		defer s.mu.RUnlock()
211		entries := []pinEntry{}
212		for cid, p := range s.pins {
213			if validPin(p, now) {
214				entries = append(entries, pinEntry{cid: cid, expiresAt: p.expiresAt})
215			}
216		}
217		sort.Slice(entries, func(i, j int) bool { return entries[i].cid < entries[j].cid })
218		return entries
219	}
220	
221	// collectGarbage removes every object with no valid pin in force at now, or
222	// only counts them when dryRun is true. It returns the affected cids in
223	// lexical order and the sum of their body sizes. The sweep is atomic with
224	// respect to pin updates and object reads.
225	func (s *store) collectGarbage(now time.Time, dryRun bool) (cids []string, totalBytes int) {
226		s.mu.Lock()
227		defer s.mu.Unlock()
228		cids = []string{}
229		for cid, obj := range s.objects {
230			if p, pinned := s.pins[cid]; pinned && validPin(p, now) {
231				continue
232			}
233			cids = append(cids, cid)
234			totalBytes += obj.size
235		}
236		sort.Strings(cids)
237		if !dryRun {
238			for _, cid := range cids {
239				obj := s.objects[cid]
240				delete(s.objects, cid)
241				s.releaseBlocks(obj)
242			}
243			for cid, p := range s.pins {
244				if !validPin(p, now) {
245					delete(s.pins, cid)
246				}
247			}
248		}
249		action := auditGCCollect
250		result := "collected"
251		if dryRun {
252			action = auditGCPreview
253			result = "previewed"
254		}
255		s.audit.append(auditRecord{
256			action:  action,
257			result:  result,
258			objects: intPtr(len(cids)),
259			bytes:   intPtr(totalBytes),
260		})
261		return cids, totalBytes
262	}
263	
264	// releaseBlocks drops the object's block references, removing any block no
265	// other live object uses. The caller must hold the write lock.
266	func (s *store) releaseBlocks(obj *object) {
267		seen := make(map[string]bool, len(obj.cids))
268		for _, c := range obj.cids {
269			if seen[c] {
270				continue
271			}
272			seen[c] = true
273			b, ok := s.blocks[c]
274			if !ok {
275				continue
276			}
277			b.refs--
278			if b.refs == 0 {
279				delete(s.blocks, c)
280			}
281		}
282	}
283	
284	// validCID reports whether s has the "sha256:<64 lowercase hex>" shape.
285	func validCID(s string) bool {
286		if len(s) != len(cidPrefix)+64 || !strings.HasPrefix(s, cidPrefix) {
287			return false
288		}
289		for _, c := range s[len(cidPrefix):] {
290			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
291				return false
292			}
293		}
294		return true
295	}
