152	// parseBundle fully validates a bundle body and, on success, returns the
153	// object ready to store. On failure it returns the error code and HTTP
154	// status to report; the store is never touched on the failure path.
155	func parseBundle(body []byte) (obj *object, code string, status int) {
156		invalid := func() (*object, string, int) {
157			return nil, "invalid_bundle", http.StatusBadRequest
158		}
159		integrity := func() (*object, string, int) {
160			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
161		}
162	
163		if !wellFormedJSON(body) {
164			return invalid()
165		}
166		var doc bundleJSON
167		dec := json.NewDecoder(bytes.NewReader(body))
168		dec.DisallowUnknownFields()
169		if err := dec.Decode(&doc); err != nil {
170			return invalid()
171		}
172		if doc.Version == nil || doc.Root == nil || doc.Blocks == nil ||
173			doc.Root.CID == nil || doc.Root.Size == nil || doc.Root.ChunkSize == nil ||
174			doc.Root.Chunks == nil {
175			return invalid()
176		}
177		for _, b := range *doc.Blocks {
178			if b.CID == nil || b.Data == nil {
179				return invalid()
180			}
181		}
182	
183		// Numeric fields must be integers. An integer outside int64 range is a
184		// value problem, not a type problem: it cannot match a supported
185		// version, chunk size or size limit.
186		version, err := parseInt(*doc.Version)
187		if err != nil {
188			if errors.Is(err, strconv.ErrRange) {
189				return nil, "unsupported_bundle", http.StatusUnprocessableEntity
190			}
191			return invalid()
192		}
193		chunkSize, err := parseInt(*doc.Root.ChunkSize)
194		if err != nil {
195			if errors.Is(err, strconv.ErrRange) {
196				return nil, "unsupported_bundle", http.StatusUnprocessableEntity
197			}
198			return invalid()
199		}
200		size, err := parseInt(*doc.Root.Size)
201		if err != nil {
202			if errors.Is(err, strconv.ErrRange) {
203				return nil, "payload_too_large", http.StatusRequestEntityTooLarge
204			}
205			return invalid()
206		}
207	
208		if !validCID(*doc.Root.CID) {
209			return invalid()
210		}
211		for _, c := range *doc.Root.Chunks {
212			if !validCID(c) {
213				return invalid()
214			}
215		}
216		blockData := make(map[string][]byte, len(*doc.Blocks))
217		for _, b := range *doc.Blocks {
218			if !validCID(*b.CID) {
219				return invalid()
220			}
221			data, err := base64.StdEncoding.DecodeString(*b.Data)
222			if err != nil {
223				return invalid()
224			}
225			blockData[*b.CID] = data
226		}
227	
228		if version != bundleVersion || chunkSize != ChunkSize {
229			return nil, "unsupported_bundle", http.StatusUnprocessableEntity
230		}
231		if size > MaxObjectSize {
232			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
233		}
234		if size < 0 {
235			return integrity()
236		}
237	
238		// The block set must be exactly the unique identifiers the manifest
239		// references: no duplicates, none missing, none unreferenced.
240		referenced := make(map[string]bool, len(*doc.Root.Chunks))
241		for _, c := range *doc.Root.Chunks {
242			referenced[c] = true
243		}
244		seen := make(map[string]bool, len(*doc.Blocks))
245		for _, b := range *doc.Blocks {
246			if seen[*b.CID] {
247				return integrity()
248			}
249			seen[*b.CID] = true
250			if !referenced[*b.CID] {
251				return integrity()
252			}
253		}
254		for c := range referenced {
255			if !seen[c] {
256				return integrity()
257			}
258		}
259	
260		// Every block identifier must be the digest of its decoded bytes.
261		for cid, data := range blockData {
262			if chunkCID(data) != cid {
263				return integrity()
264			}
265		}
266	
267		// Rebuild the body in manifest order under the fixed chunking rules:
268		// every chunk but the last is exactly ChunkSize, the last is 1..ChunkSize,
269		// and an empty object carries no chunks at all.
270		chunks := *doc.Root.Chunks
271		if size == 0 && len(chunks) != 0 {
272			return integrity()
273		}
274		if size > 0 && len(chunks) == 0 {
275			return integrity()
276		}
277		total := 0
278		for i, c := range chunks {
279			n := len(blockData[c])
280			if i < len(chunks)-1 {
281				if n != ChunkSize {
282					return integrity()
283				}
284			} else if n < 1 || n > ChunkSize {
285				return integrity()
286			}
287			total += n
288		}
289		if total > MaxObjectSize {
290			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
291		}
292		if total != size {
293			return integrity()
294		}
295		if rootCID(size, chunks) != *doc.Root.CID {
296			return integrity()
297		}
298	
299		obj = &object{
300			cid:    *doc.Root.CID,
301			size:   size,
302			chunks: make([][]byte, 0, len(chunks)),
303			cids:   append([]string{}, chunks...),
304		}
305		for _, c := range chunks {
306			obj.chunks = append(obj.chunks, blockData[c])
307		}
308		return obj, "", 0
309	}
