311	// wellFormedJSON reports whether data is a single well-formed JSON value
312	// with no duplicate object keys and nothing but whitespace after it.
313	func wellFormedJSON(data []byte) bool {
314		dec := json.NewDecoder(bytes.NewReader(data))
315		var walk func() bool
316		walk = func() bool {
317			tok, err := dec.Token()
318			if err != nil {
319				return false
320			}
321			delim, ok := tok.(json.Delim)
322			if !ok {
323				return true
324			}
325			switch delim {
326			case '{':
327				seen := make(map[string]bool)
328				for dec.More() {
329					key, err := dec.Token()
330					if err != nil {
331						return false
332					}
333					name, ok := key.(string)
334					if !ok || seen[name] {
335						return false
336					}
337					seen[name] = true
338					if !walk() {
339						return false
340					}
341				}
342				_, err := dec.Token()
343				return err == nil
344			case '[':
345				for dec.More() {
346					if !walk() {
347						return false
348					}
349				}
350				_, err := dec.Token()
351				return err == nil
352			}
353			return false
354		}
355		if !walk() {
356			return false
357		}
