		[]byte(`{"version":1,"entries":[{"name":"a","type":"file","cid":"sha256:` + strings.Repeat("0", 64) + `"}]}`), // unsorted is fine alone; replace below
		[]byte(`{"version":1,"entries":[{"name":"b","type":"file","cid":"sha256:` + strings.Repeat("0", 64) + `"},{"name":"a","type":"file","cid":"sha256:` + strings.Repeat("0", 64) + `"}]}`),
