	if code, _, _ := get("/v1/gateway/" + rootCID + "/a%2Fb"); code != 400 {
		t.Fatalf("a%2Fb code = %d, want 400", code)
	}
	// Raw .. must reach the gateway and be rejected, not 307-redirected.
	loc, err := http.Get(ts.URL + "/v1/gateway/" + rootCID + "/a/../b")
	if err != nil {
		t.Fatal(err)
	}
	loc.Body.Close()
	if loc.StatusCode != 400 {
		t.Fatalf("raw .. path code = %d, want 400 (Location=%q)", loc.StatusCode, loc.Header.Get("Location"))
	}
	// Root directory.
	if code, ct, _ := get("/v1/gateway/" + rootCID); code != 200 || !strings.HasPrefix(ct, "application/vnd.cidvault.directory") {
		t.Fatalf("root dir: %d %q", code, ct)
	}
	// Existing endpoints still behave.
	resp, err := http.Get(ts.URL + "/healthz")
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if resp.StatusCode != 200 {
		t.Fatalf("healthz = %d", resp.StatusCode)
	}
}
